/* @lc app=leetcode id=3067 lang=kotlin */
class Solution { fun countPairsOfConnectableServers(edges: Array<IntArray>, signalSpeed: Int): IntArray = (edges.size + 1).let { n -> Array(n) { mutableListOf<Pair<Int, Int>>() }.also { adj -> edges.forEach { (u, v, w) -> adj[u].add(v to w).also { adj[v].add(u to w) } } }.let { adj -> IntArray(n) { r -> DeepRecursiveFunction<Triple<Int, Int, Int>, Int> { (u, p, dist) -> (if (dist % signalSpeed == 0) 1 else 0) + adj[u].filter { it.first != p }.sumOf { (v, w) -> callRecursive(Triple(v, u, dist + w)) } }.let { dfs -> adj[r].map { (v, w) -> dfs(Triple(v, r, w)) }.let { counts -> counts.indices.sumOf { i -> (i + 1 until counts.size).sumOf { j -> counts[i] * counts[j] } } } } } } } }